CREATE TABLE users (id VARCHAR(64) PRIMARY KEY, data LONGTEXT NOT NULL, version BIGINT NOT NULL DEFAULT 0, CONSTRAINT users_json CHECK (JSON_VALID(data)));
CREATE TABLE portfolios (id VARCHAR(64) PRIMARY KEY, data LONGTEXT NOT NULL, version BIGINT NOT NULL DEFAULT 0, CONSTRAINT portfolios_json CHECK (JSON_VALID(data)));
CREATE TABLE portfolio_members (id VARCHAR(64) PRIMARY KEY, data LONGTEXT NOT NULL, version BIGINT NOT NULL DEFAULT 0, CONSTRAINT portfolio_members_json CHECK (JSON_VALID(data)));
CREATE TABLE orders (id VARCHAR(64) PRIMARY KEY, data LONGTEXT NOT NULL, version BIGINT NOT NULL DEFAULT 0, CONSTRAINT orders_json CHECK (JSON_VALID(data)));
CREATE TABLE executions (id VARCHAR(64) PRIMARY KEY, data LONGTEXT NOT NULL, version BIGINT NOT NULL DEFAULT 0, CONSTRAINT executions_json CHECK (JSON_VALID(data)));
CREATE TABLE trade_audit (id VARCHAR(64) PRIMARY KEY, data LONGTEXT NOT NULL, version BIGINT NOT NULL DEFAULT 0, CONSTRAINT trade_audit_json CHECK (JSON_VALID(data)));
CREATE TABLE outbox (id VARCHAR(64) PRIMARY KEY, data LONGTEXT NOT NULL, version BIGINT NOT NULL DEFAULT 0, CONSTRAINT outbox_json CHECK (JSON_VALID(data)));
CREATE TABLE processed_events (id VARCHAR(64) PRIMARY KEY, data LONGTEXT NOT NULL, version BIGINT NOT NULL DEFAULT 0, CONSTRAINT processed_events_json CHECK (JSON_VALID(data)));
CREATE TABLE idempotency (id VARCHAR(64) PRIMARY KEY, data LONGTEXT NOT NULL, version BIGINT NOT NULL DEFAULT 0, CONSTRAINT idempotency_json CHECK (JSON_VALID(data)));
ALTER TABLE orders ADD COLUMN portfolio_id VARCHAR(64) GENERATED ALWAYS AS (JSON_UNQUOTE(JSON_EXTRACT(data,'$.portfolioId'))) STORED, ADD INDEX orders_portfolio (portfolio_id);
ALTER TABLE executions ADD COLUMN external_key VARCHAR(255) GENERATED ALWAYS AS (JSON_UNQUOTE(JSON_EXTRACT(data,'$.externalKey'))) STORED, ADD UNIQUE KEY executions_external (external_key);